window.RP_SESSION={"id":"S-b13a54b8ffa0","messages":[{"id":"RP-II-0195089","time":"2026-09-16T02:44:00+09:00","room":"RP II","name":"오즈발드 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"오늘도 강가에서 퐁퐁퐁…","characters":["P-d40bea4fdee0"]},{"id":"RP-II-0195090","time":"2026-09-16T02:44:00+09:00","room":"RP II","name":"오즈발드 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"오즈발드는 평소보다도 늦은 시간까지 밖에 나와있네요.","characters":["P-d40bea4fdee0"]},{"id":"RP-II-0195091","time":"2026-09-16T02:45:00+09:00","room":"RP II","name":"오즈발드 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"퐁퐁퐁퐁…","characters":["P-d40bea4fdee0"]},{"id":"RP-II-0195092","time":"2026-09-16T02:47:00+09:00","room":"RP II","name":"오즈발드 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"…퐁퐁퐁퐁퐁…","characters":["P-d40bea4fdee0"]},{"id":"RP-II-0195093","time":"2026-09-16T02:50:00+09:00","room":"RP II","name":"오즈발드 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"이모티콘","characters":["P-d40bea4fdee0"]},{"id":"RP-II-0195094","time":"2026-09-16T02:51:00+09:00","room":"RP II","name":"오즈발드 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"퐁퐁퐁퐁…","characters":["P-d40bea4fdee0"]},{"id":"RP-II-0195095","time":"2026-09-16T02:51:00+09:00","room":"RP II","name":"오드리","profile":"오드리","identity":"unresolved","type":"dialogue","body":"퐁퐁..","characters":[]},{"id":"RP-II-0195096","time":"2026-09-16T02:51:00+09:00","room":"RP II","name":"오즈발드 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“…클레이 님, 그리하여 이 놀이는 어떤 놀이입니까? 요즘들어 부쩍 자주 하시는 것 같습니다.”","characters":["P-d40bea4fdee0"]},{"id":"RP-II-0195097","time":"2026-09-16T02:52:00+09:00","room":"RP II","name":"오즈발드 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"[ 그냥요, 물방울 만들기 놀이에요. ]","characters":["P-d40bea4fdee0"]},{"id":"RP-II-0195098","time":"2026-09-16T02:52:00+09:00","room":"RP II","name":"오즈발드 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“…그렇습니까…”","characters":["P-d40bea4fdee0"]},{"id":"RP-II-0195099","time":"2026-09-16T02:52:00+09:00","room":"RP II","name":"오즈발드 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”음, 즐거우시다면 다행입니다.“","characters":["P-d40bea4fdee0"]},{"id":"RP-II-0195100","time":"2026-09-16T02:53:00+09:00","room":"RP II","name":"오즈발드 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"[ 아하하, 아뇨~ 막 그렇게 즐겁고 그런건 아니구요. ]","characters":["P-d40bea4fdee0"]},{"id":"RP-II-0195101","time":"2026-09-16T02:53:00+09:00","room":"RP II","name":"오즈발드 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"[ 오즈, 최근에 우리가 오즈의 지도를 그리러 밖으로 나간 적이 몇번이나 있었나요? ]","characters":["P-d40bea4fdee0"]},{"id":"RP-II-0195102","time":"2026-09-16T02:54:00+09:00","room":"RP II","name":"오즈발드 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”음… 아마 한두번 쯤인 것 같습니다.“","characters":["P-d40bea4fdee0"]},{"id":"RP-II-0195103","time":"2026-09-16T02:55:00+09:00","room":"RP II","name":"오즈발드 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"[ 그거에요! 우린 분명 오즈의 지도를 완성하기 위해 마을을 떠나온거잖아요. ]","characters":["P-d40bea4fdee0"]},{"id":"RP-II-0195104","time":"2026-09-16T02:56:00+09:00","room":"RP II","name":"오즈발드 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"[ 그런데 골기아에 들어온 이후부터는 오즈가 펜을 잡고 지도를 그리는걸 본 적이 얼마나 있어야 말이에요. 혹시 무슨 일 있나요? ]","characters":["P-d40bea4fdee0"]},{"id":"RP-II-0195105","time":"2026-09-16T02:57:00+09:00","room":"RP II","name":"오즈발드 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“…아, 클레이 님께서도 알아차리신 것 같습니다.“","characters":["P-d40bea4fdee0"]},{"id":"RP-II-0195106","time":"2026-09-16T02:59:00+09:00","room":"RP II","name":"오즈발드 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”그게… 지도 제작자가 된 사람으로써 클레이 님께 이런 말씀을 드리게 되어 부끄럽습니다만, 최근에 들어서 지금의 저는 과연 제대로 된 지도를 그려오고 있는 것인지 문득 의문이 떠올랐습니다.“","characters":["P-d40bea4fdee0"]},{"id":"RP-II-0195107","time":"2026-09-16T03:01:00+09:00","room":"RP II","name":"오즈발드 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”마을을 벗어나 여러 장소들을 지나고, 마침내 골기아에 다다르기까지. 그동안 주변의 장소들을 알아두기 위해 여러장의 다른 지도 제작자 분들의 지도를 구입해왔었지만… 그분들의 지도를 직접 눈에 세길 때마다, 제게 점점 알 수 없는 회의감이 들었습니다.“","characters":["P-d40bea4fdee0"]},{"id":"RP-II-0195108","time":"2026-09-16T03:03:00+09:00","room":"RP II","name":"오즈발드 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”마을에서부터 꿈을 꾸고 커다란 세상에 발걸음을 내딛은 이 작은 한 사람에게는, 이미 세상을 누비며 먼저 길을 걸어가신 모든 분들의 결과들이 너무나 멀게도 느껴졌었던 것 같습니다.“","characters":["P-d40bea4fdee0"]},{"id":"RP-II-0195109","time":"2026-09-16T03:05:00+09:00","room":"RP II","name":"오즈발드 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”그분들의 지도에 비하여, 저의 수첩과 양피지에 그려진 저의 지도들은 어찌 보면 난잡하기도 하였으며 때론 텅 빈 것 처럼 보이기도 하였습니다.\n…저는 그저 겁을 먹은 듯 합니다. 제가 너무나도 커다란 꿈을 꾼 것은 아닐까, 이대로 마을을 떠나온 것이 옳은 것이었을까 하는…”","characters":["P-d40bea4fdee0"]},{"id":"RP-II-0195110","time":"2026-09-16T03:06:00+09:00","room":"RP II","name":"오즈발드 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“…아닙니다. 우선은 저의 힘 만으로 닿을 수 있는 곳까지 노력부터 해봐야 하지 않겠습니까. 이렇게 제자리에 머물러, 지레 겁을 먹은 채 꿈을 접어둘 수야 없지요.”","characters":["P-d40bea4fdee0"]},{"id":"RP-II-0195111","time":"2026-09-16T03:08:00+09:00","room":"RP II","name":"오즈발드 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“…그 전까지 잠시 저의 마음을 다시 먹어두는, 그런 시간을 가져보는 중입니다. 과연 저만의 지도란 무엇인지, 또한 저는 그것을 끝내 그려낼 수 있을지에 대한 고민을 하는 중입니다.”","characters":["P-d40bea4fdee0"]},{"id":"RP-II-0195112","time":"2026-09-16T03:10:00+09:00","room":"RP II","name":"오즈발드 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"오즈발드는 클레이가 쏘아대는 큰 물방울들을 멀뚱멀뚱 바라보았습니다.","characters":["P-d40bea4fdee0"]},{"id":"RP-II-0195113","time":"2026-09-16T03:10:00+09:00","room":"RP II","name":"오즈발드 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"퐁퐁퐁퐁…","characters":["P-d40bea4fdee0"]},{"id":"RP-II-0195114","time":"2026-09-16T03:10:00+09:00","room":"RP II","name":"오즈발드 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-d40bea4fdee0"]},{"id":"RP-II-0195115","time":"2026-09-16T03:10:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... to be continue.","characters":[]}]};
